-- 1. Permissões de RLS para acesso pelo app web (anon e authenticated)
DO $$
DECLARE tbl text;
BEGIN
  FOR tbl IN SELECT tablename FROM pg_tables WHERE schemaname = 'public' LOOP
    EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', 'policy_public_all_' || tbl, tbl);
    EXECUTE format('CREATE POLICY %I ON public.%I FOR ALL TO public USING (true) WITH CHECK (true)', 'policy_public_all_' || tbl, tbl);
  END LOOP;
END $$;

